#!/usr/bin/env Rscript

# ==============================================================================
# Analyze Repeated Inference Runs
# ==============================================================================
# This script analyzes the stability of model predictions across multiple runs.
# It expects the directory structure generated by `slurm_inference_repeated.sh`.
#
# Usage:
#   Rscript statistics/analyze_repeated_inference.R --dir /path/to/repeated_run_YYYYMMDD_HHMMSS
# ==============================================================================

# Check for required packages
required_packages <- c("tidyverse", "irr", "optparse")
new_packages <- required_packages[!(required_packages %in% installed.packages()[,"Package"])]
if(length(new_packages)) install.packages(new_packages, repos = "http://cran.us.r-project.org")

library(tidyverse)
library(irr)
library(optparse)

# ==============================================================================
# Arguments definition
# ==============================================================================
option_list <- list(
  make_option(c("-d", "--dir"), type="character", default=NULL, 
              help="Path to the repeated_run directory output (required)", metavar="character"),
  make_option(c("-o", "--output"), type="character", default="stability_analysis_report.txt", 
              help="Output report filename [default= %default]", metavar="character")
) 

opt_parser <- OptionParser(option_list=option_list)
opt <- parse_args(opt_parser)

if (is.null(opt$dir)) {
  print_help(opt_parser)
  stop("Input directory must be supplied with --dir", call.=FALSE)
}

base_dir <- opt$dir
output_file <- file.path(base_dir, opt$output)

# Redirect output to file and console
sink(output_file, split=TRUE)

cat("==============================================================================\n")
cat("STABILITY ANALYSIS REPORT\n")
cat("==============================================================================\n")
cat("Target Directory:", base_dir, "\n")
cat("Analysis Date:", as.character(Sys.time()), "\n\n")

# ==============================================================================
# Helper Functions
# ==============================================================================

# Function to calculate Quadratic Weighted Kappa
calc_qwk <- function(rater1, rater2) {
  # Ensure factors present all levels 1-5 to keep matrix square if possible
  levels <- 1:5
  raters <- data.frame(
    R1 = factor(rater1, levels = levels),
    R2 = factor(rater2, levels = levels)
  )
  
  # Remove NAs
  raters <- na.omit(raters)
  
  if(nrow(raters) == 0) return(NA)
  
  kappa_res <- kappa2(raters, weight = "squared")
  return(kappa_res$value)
}

# Function to find the prediction content
# Handles the variable structure: run_X/model/model/inference_TIMESTAMP/predictions.csv
find_prediction_file <- function(base, run_num, model_name) {
  # Search pattern: run_{run_num}/{model_name}/**/predictions.csv
  # We use recursive globbing
  
  # Construct path to the model folder inside the run
  # Based on user tree: repeated_run.../run_1/resnet50/resnet50/inference...
  # It seems there is a double folder nesting: run_1/resnet50/resnet50/
  
  run_path <- file.path(base, paste0("run_", run_num))
  
  # Try simple wildcard search
  files <- list.files(run_path, pattern = "predictions.csv", recursive = TRUE, full.names = TRUE)
  
  # Filter for model name if needed, though run_path might already restrict it slightly?
  # No, run_path contains all models.
  # Let's search specifically for the model string in path
  model_files <- files[grep(paste0("/", model_name, "/"), files)]
  
  if (length(model_files) == 0) {
    return(NULL)
  }
  
  # Return the first match (assumes one inference run per folder structure)
  return(model_files[1])
}

# ==============================================================================
# Main Analysis Loop
# ==============================================================================

models <- c("resnet50", "efficientnet_b3", "convnext_tiny")
runs <- 1:3

results_summary <- list()

for (model in models) {
  cat("------------------------------------------------------------------------------\n")
  cat(toupper(model), "ANALYSIS\n")
  cat("------------------------------------------------------------------------------\n")
  
  # Load data for all 3 runs
  run_data <- list()
  
  for (r in runs) {
    fpath <- find_prediction_file(base_dir, r, model)
    
    if (is.null(fpath) || !file.exists(fpath)) {
      cat(sprintf("  [WARNING] Missing file for Run %d. Skipping model analysis.\n", r))
      run_data[[r]] <- NULL
    } else {
      cat(sprintf("  Found Run %d: ...%s\n", r, substr(fpath, nchar(fpath)-40, nchar(fpath))))
      df <- read_csv(fpath, show_col_types = FALSE) %>%
        select(filename, true_pai, predicted_pai, starts_with("prob_pai"))
      
      # Rename columns with suffix
      colnames(df)[3:ncol(df)] <- paste0(colnames(df)[3:ncol(df)], "_r", r)
      run_data[[r]] <- df
    }
  }
  
  # Check if we have all runs
  if (any(sapply(run_data, is.null))) {
    cat("  Incomplete data. Skipping.\n\n")
    next
  }
  
  # Merge dataframes
  full_df <- run_data[[1]] %>%
    inner_join(run_data[[2]], by = c("filename", "true_pai")) %>%
    inner_join(run_data[[3]], by = c("filename", "true_pai"))
  
  cat("  Total images matched across 3 runs:", nrow(full_df), "\n\n")
  
  # --- 1. Performance Statistics per Run ---
  cat("  Performance (QWK vs Ground Truth):\n")
  qwk_r1 <- calc_qwk(full_df$true_pai, full_df$predicted_pai_r1)
  qwk_r2 <- calc_qwk(full_df$true_pai, full_df$predicted_pai_r2)
  qwk_r3 <- calc_qwk(full_df$true_pai, full_df$predicted_pai_r3)
  
  cat(sprintf("    Run 1 QWK: %.4f\n", qwk_r1))
  cat(sprintf("    Run 2 QWK: %.4f\n", qwk_r2))
  cat(sprintf("    Run 3 QWK: %.4f\n", qwk_r3))
  
  sd_perf <- sd(c(qwk_r1, qwk_r2, qwk_r3))
  cat(sprintf("    Std Dev:   %.6f %s\n", sd_perf, 
              ifelse(sd_perf < 0.0001, "(Stable)", "(Variance detected)")))
  
  # --- 2. Reproducibility (Pairwise QWK) ---
  cat("\n  Reproducibility (Inter-Run Agreement QWK):\n")
  rep_1v2 <- calc_qwk(full_df$predicted_pai_r1, full_df$predicted_pai_r2)
  rep_2v3 <- calc_qwk(full_df$predicted_pai_r2, full_df$predicted_pai_r3)
  rep_1v3 <- calc_qwk(full_df$predicted_pai_r1, full_df$predicted_pai_r3)
  
  cat(sprintf("    Run 1 vs Run 2: %.4f\n", rep_1v2))
  cat(sprintf("    Run 2 vs Run 3: %.4f\n", rep_2v3))
  cat(sprintf("    Run 1 vs Run 3: %.4f\n", rep_1v3))
  
  perfect_reproducibility <- (rep_1v2 == 1 && rep_2v3 == 1 && rep_1v3 == 1)
  if (perfect_reproducibility) {
    cat("    RESULT: PERFECT CONSISTENCY in class predictions.\n")
  } else {
    cat("    RESULT: Minor inconsistencies detected.\n")
  }
  
  # --- 3. Probability Stability ---
  # Calculate max absolute difference in probabilities for the predicted class
  # We look at the prob of the predicted class in Run 1, vs same class prob in Run 2/3
  
  # Simpler metric: Average variance of the probability vector across 3 runs per sample
  cat("\n  Probability Drift Analysis:\n")
  
  # Check if predictions are identical for all rows
  identical_preds <- with(full_df, 
                          predicted_pai_r1 == predicted_pai_r2 & 
                          predicted_pai_r2 == predicted_pai_r3)
  
  pct_id <- mean(identical_preds) * 100
  cat(sprintf("    Percentage of Identical Predictions: %.2f%%\n", pct_id))
  
  if (pct_id < 100) {
    cat("    Discrepancies found in filenames:\n")
    discrepancies <- full_df[!identical_preds, c("filename", "predicted_pai_r1", "predicted_pai_r2", "predicted_pai_r3")]
    print(head(discrepancies))
    if(nrow(discrepancies) > 6) cat("    ... and", nrow(discrepancies)-6, "more.\n")
  }
  
  # Check probability drift (Max diff between any two runs for any class)
  # This is computationally intensive in R loops, but fast vectorwise
  p_diff_1_2 <- abs(full_df[, grep("_r1", names(full_df))] - full_df[, grep("_r2", names(full_df))])
  p_diff_2_3 <- abs(full_df[, grep("_r2", names(full_df))] - full_df[, grep("_r3", names(full_df))])
  p_diff_1_3 <- abs(full_df[, grep("_r1", names(full_df))] - full_df[, grep("_r3", names(full_df))])
  
  max_diff <- max(c(max(p_diff_1_2), max(p_diff_2_3), max(p_diff_1_3)))
  mean_diff <- mean(c(as.matrix(p_diff_1_2), as.matrix(p_diff_2_3), as.matrix(p_diff_1_3)))
  
  cat(sprintf("    Max Probability Difference:  %.8f\n", max_diff))
  cat(sprintf("    Mean Probability Difference: %.8f\n", mean_diff))
  
  cat("\n")
}

cat("==============================================================================\n")
cat("ANALYSIS COMPLETE\n")
cat("==============================================================================\n")
cat("Report saved to:", output_file, "\n")
sink()

# Print location to console
cat("\nAnalysis complete! Report saved to:\n")
cat(output_file, "\n")
